<script>$(function(){function safe(v){return $('<div>').text(v == null || v === '' ? 'Not recorded' : String(v)).html();}function renderValues(values){var html='';Object.keys(values || {}).forEach(function(key){var value=values[key];if(value !== null && typeof value === 'object'){value=JSON.stringify(value);};html+='<div><dt>'+safe(String(key).replace(/[_-]/g,' '))+'</dt><dd>'+safe(value)+'</dd></div>';});return html||'<div><dt>Context</dt><dd>No additional context recorded.</dd></div>';};$('.audit-detail').on('click',function(){var b=$(this), context={};try{context=JSON.parse(b.attr('data-context')||'{}');}catch(e){}$('#pharmacy-audit-detail-title').text(b.attr('data-action-label')||'Audit event details');$('#pharmacy-audit-detail-values').html('<div><span>Action</span><strong>'+safe(b.attr('data-action')||'Audit event')+'</strong></div><div><span>Performed by</span><strong>'+safe(b.attr('data-actor'))+'</strong></div><div><span>Date and time</span><strong>'+safe(b.attr('data-time'))+'</strong></div><div><span>Route</span><strong>'+safe(b.attr('data-route'))+'</strong></div><div><span>Correlation</span><strong>'+safe(b.attr('data-correlation'))+'</strong></div>');$('#pharmacy-audit-context-values').html(renderValues(context));});});</script>
